changeSet.sql:
INSERT INTO m_permission (grouping, code, entity_name, action_name, can_maker_checker) SELECT 'POCKET', 'LINK_ACCOUNT_TO_POCKET', 'POCKET', 'LINK_ACCOUNT_TO', false WHERE NOT EXISTS (SELECT 1 FROM m_permission WHERE code = 'LINK_ACCOUNT_TO_POCKET');
INSERT INTO m_permission (grouping, code, entity_name, action_name, can_maker_checker) SELECT 'POCKET', 'DELINK_ACCOUNT_FROM_POCKET', 'POCKET', 'DELINK_ACCOUNT_FROM', false WHERE NOT EXISTS (SELECT 1 FROM m_permission WHERE code = 'DELINK_ACCOUNT_FROM_POCKET');
INSERT INTO m_role_permission (role_id, permission_id) SELECT r.id, p.id FROM m_role r CROSS JOIN m_permission p WHERE r.name = 'Self Service User' AND p.code IN ('LINK_ACCOUNT_TO_POCKET', 'DELINK_ACCOUNT_FROM_POCKET') AND NOT EXISTS ( SELECT 1 FROM m_role_permission rp WHERE rp.role_id = r.id AND rp.permission_id = p.id );
